import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId, parseDate, fetchPostH, getUrlServerSide, compareJSON, fetchEncryptStream, qryStore } from "../../../stores/Utils";

import { CheckBoxSlide_Cmpt, TextInput_Cmpt, CheckBox_Cmpt } from "../../../components";


import "./dashboard.css"
import { CloseModal } from "../../../components/DialogHRM";

const CheckBoxSlide = CheckBoxSlide_Cmpt();
const TextInput = TextInput_Cmpt();

const CheckBox = CheckBox_Cmpt();

const frmNm = "upd_account"

const UpdAccount  = ({data, confirm}) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};



	const save  = async ()  => {
		let ffm = getStore(frmNm);
		let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )

		
		let bdyq2 = {...getStore(qryStore())?.upd_acc};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			accountId: ffm["accountId"],
		}
		bdyq2.data2update=diff.data;

		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			updStore(frmNm + "_bck", {});
			confirm && confirm();
			data?.modalID && CloseModal({id:data?.modalID})
		}
		
	};

	let flds = ["code","name","clasification", "type","payOrCollect", "ignoreGroupByDocs"]

	let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )




	const clean = (f) => {
		updStore(frmNm, {});
		set_obs(gen16CodeId())
	};

	
	

	return (
		<div
		style={{
			maxHeight: "80vh",
			width: "560px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					Actualizar Cuenta
				</p>
				<div className="flexSpace"/>
				
			</div>

			<div className="_dsplFlx ">
				<TextInput  
					init={getStore(frmNm)?.["code"]} 
					label={"Codigo"} 
					width={120} 
					updChanges={(e)=>updFrm("code",e)}
				/>
				<div className="flexSpace"/>
				<div className="_dsplFlx " style={{padding: "18px"}}>
					<div className="flexSpace"/>
					<CheckBox data={[
							{label: "Real", id:"real"},
							{label: "Nominal", id:"nominal"}
						]}
						active={getStore(frmNm)?.["clasification"]}
						updSelect={(e)=>updFrm("clasification",e)}
					/>
					<div className="flexSpace"/>
				</div>
			</div>
			<TextInput  
				init={getStore(frmNm)?.["name"]} 
				label={"Nombre"} 
				width={520} 
				updChanges={(e)=>updFrm("name",e)}
			/>

			<div className="_dsplFlx " style={{padding: "18px"}}>
				<div className="flexSpace"/>
				<CheckBox 
					data={[
						{label: "Deudoras", id:"debit"},
						{label: "Acredoras", id:"credit"}
						
					]}
					active={getStore(frmNm)?.["type"]}
					updSelect={(e)=>updFrm("type",e)}
				/>
				<div className="flexSpace"/>
			</div>


			<div className="_dsplFlx " style={{marginTop: 20}}>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["ignoreGroupByDocs"]}
					keyCode={57}
					updChange={(e)=>updFrm("ignoreGroupByDocs",e)}
				/>
				<span className={`checklabel`}>
					{"Ignorar Agrupacion Por Documentos"}
				</span>
			</div>

			

			<div className="_dsplFlx " style={{padding: "18px"}}>
				<div className="flexSpace"/>
				<CheckBox 
					data={[
						{label: "Regular", id:null},
						{label: "Pago", id:"pay"},
						{label: "Cobro", id:"collect"}
					]}
					active={getStore(frmNm)?.["payOrCollect"] || null}
					updSelect={(e)=>updFrm("payOrCollect",e)}
				/>
				<div className="flexSpace"/>
			</div>

			
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				{diff?.hasChange ?
				<div className="card">
					<button onClick={save}>
						Actualizar
					</button>
				</div>
				:null}
			</div>
		

			
		</div>
	);
};

export default UpdAccount;
